  "source": "def audit(events, at):
    eligible = [event for event in events if event['seen'] <= at]
    fences = {}
    selected = {}
    for event in eligible:
        selected.setdefault(event['key'], {})
        if event['kind'] == 'fence':
            slot = (event['key'], event['side'])
            fences[slot] = max(fences.get(slot, 0), event['through'])
    for event in eligible:
        if event['kind'] != 'ack':
            continue
        key, side = event['key'], event['side']
        epoch, digest = event['epoch'], event['digest']
        if epoch <= fences.get((key, side), 0):
            continue
        sides = selected[key]
        old = sides.get(side)
        if old is None or epoch > old[0]:
            sides[side] = (epoch, {digest})
        elif epoch == old[0]:
            old[1].add(digest)
    result = {}
    for key, sides in selected.items():
        if not sides:
            result[key] = 'withdrawn'
        elif any(len(value[1]) > 1 for value in sides.values()):
            result[key] = 'conflict'
        elif 'L' not in sides or 'R' not in sides:
            result[key] = 'pending'
        elif sides['L'][0] != sides['R'][0]:
            result[key] = 'pending'
        elif sides['L'][1] != sides['R'][1]:
            result[key] = 'diverged'
        else:
            result[key] = 'verified'
    return result
